#!/usr/bin/env python3
from pathlib import Path

p = Path('src/core/core_lower.c')
s = p.read_text()
if 'CORE_M106_SCALAR' in s:
    print('M106 diagnostic already applied')
    raise SystemExit(0)

old = '''    expression = minic_c0_program_expression(context->body->program, expression_id);\n    if (expression == NULL ||\n        !minic_c0_assignment_compatible(context->body->program, target_type, expression_id)) {\n        return MINIC_CORE_LOWER_UNSUPPORTED;\n    }\n'''
new = '''    expression = minic_c0_program_expression(context->body->program, expression_id);\n    if (expression == NULL) {\n        return MINIC_CORE_LOWER_ERROR;\n    }\n    if (!minic_c0_assignment_compatible(context->body->program, target_type, expression_id)) {\n        if (context->source_function != NULL &&\n            strcmp(context->source_function->name, "force_compatible_cpus_allowed_ptr") == 0) {\n            const MinicExpression *operand = NULL;\n            const MinicLocal *local = NULL;\n            MinicArrayObjectInfo array_info;\n            bool has_array_info = false;\n            (void)memset(&array_info, 0, sizeof(array_info));\n            if (expression->kind == MINIC_EXPRESSION_ADDRESS_OF) {\n                operand = minic_c0_program_expression(\n                    context->body->program, expression->value.unary.operand);\n                if (operand != NULL) {\n                    has_array_info = minic_c0_expression_array_object_info(\n                        context->body->program, operand, &array_info);\n                    if (operand->kind == MINIC_EXPRESSION_LOCAL) {\n                        local = minic_c0_program_local(\n                            context->body->program, operand->value.local_id);\n                    }\n                }\n            }\n            (void)fprintf(stderr,\n                          "CORE_M106_SCALAR stage=compat target_ptr=%d target_array=%d target_record=%d "\n                          "target_depth=%u expr_kind=%d expr_ptr=%d expr_array=%d expr_record=%d "\n                          "expr_depth=%u fixed_compat=%d operand_kind=%d operand_ptr=%d "\n                          "operand_array=%d operand_record=%d array_info=%d array_materialized=%d "\n                          "array_count=%zu local_array=%d local_count=%zu\\n",\n                          minic_type_is_pointer(target_type) ? 1 : 0,\n                          minic_type_is_array(target_type) ? 1 : 0,\n                          minic_type_is_record(target_type) ? 1 : 0,\n                          target_type.pointer_depth,\n                          (int)expression->kind,\n                          minic_type_is_pointer(expression->type) ? 1 : 0,\n                          minic_type_is_array(expression->type) ? 1 : 0,\n                          minic_type_is_record(expression->type) ? 1 : 0,\n                          expression->type.pointer_depth,\n                          minic_c0_fixed_call_argument_compatible(\n                              context->body->program, target_type, expression_id) ? 1 : 0,\n                          operand != NULL ? (int)operand->kind : -1,\n                          operand != NULL && minic_type_is_pointer(operand->type) ? 1 : 0,\n                          operand != NULL && minic_type_is_array(operand->type) ? 1 : 0,\n                          operand != NULL && minic_type_is_record(operand->type) ? 1 : 0,\n                          has_array_info ? 1 : 0,\n                          has_array_info && array_info.has_materialized_type ? 1 : 0,\n                          has_array_info ? array_info.element_count : 0U,\n                          local != NULL && local->is_array ? 1 : 0,\n                          local != NULL ? local->element_count : 0U);\n        }\n        return MINIC_CORE_LOWER_UNSUPPORTED;\n    }\n'''
if s.count(old) != 1:
    raise SystemExit(f'compat anchor count={s.count(old)}')
s = s.replace(old, new, 1)

old = '''    status = lower_expression(context, expression_id, &source_value);\n    if (status != MINIC_CORE_LOWER_OK) {\n        return status;\n    }\n    if (source_value >= context->function->value_count) {\n'''
new = '''    status = lower_expression(context, expression_id, &source_value);\n    if (status != MINIC_CORE_LOWER_OK) {\n        if (context->source_function != NULL &&\n            strcmp(context->source_function->name, "force_compatible_cpus_allowed_ptr") == 0) {\n            (void)fprintf(stderr,\n                          "CORE_M106_SCALAR stage=expression status=%d expr_kind=%d target_ptr=%d expr_ptr=%d\\n",\n                          (int)status, (int)expression->kind,\n                          minic_type_is_pointer(target_type) ? 1 : 0,\n                          minic_type_is_pointer(expression->type) ? 1 : 0);\n        }\n        return status;\n    }\n    if (source_value >= context->function->value_count) {\n'''
if s.count(old) != 1:
    raise SystemExit(f'expression anchor count={s.count(old)}')
s = s.replace(old, new, 1)
p.write_text(s)
print('M106 fixed-call diagnostic applied')
